#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define MAX_COURSES 100
#define MAX_NAME_LEN 50

typedef struct Course {
    char name[MAX_NAME_LEN];
    int credits;
    int prereq_count;
    int prereqs[MAX_COURSES];
    int taken;
    int in_degree; // for topological sorting
} Course;

Course courses[MAX_COURSES];
int course_count = 0;

int find_course(char *name) {
    for (int i = 0; i < course_count; i++) {
        if (strcmp(courses[i].name, name) == 0) return i;
    }
    return -1;
}

int compare(const void *a, const void *b) {
    return ((Course*)a)->credits - ((Course*)b)->credits;
}

int main() {
    int U;
    scanf("%d", &U);

    char line[1000];
    while (fgets(line, sizeof(line), stdin)) {
        if (line[0] == '\n' || line[0] == '\0') continue;
        line[strcspn(line, "\n")] = 0;

        char *token = strtok(line, " ");
        if (token == NULL) continue;

        strcpy(courses[course_count].name, token);
        courses[course_count].prereq_count = 0;
        courses[course_count].taken = 0;
        courses[course_count].in_degree = 0;

        token = strtok(NULL, " ");
        if (token == NULL) continue;
        courses[course_count].credits = atoi(token);

        while ((token = strtok(NULL, " ")) != NULL) {
            int prereq_idx = find_course(token);
            if (prereq_idx == -1) {
                // Should not happen in valid input, but handle gracefully
                continue;
            }
            courses[course_count].prereqs[courses[course_count].prereq_count++] = prereq_idx;
            courses[course_count].in_degree++;
        }
        course_count++;
    }

    // Sort courses by credits (ascending)
    qsort(courses, course_count, sizeof(Course), compare);

    int total_credits = 0;
    int courses_taken = 0;
    int taken[MAX_COURSES] = {0};

    while (total_credits < U) {
        // Find the smallest credit course that can be taken
        int best = -1;
        for (int i = 0; i < course_count; i++) {
            if (taken[i]) continue;

            // Check prerequisites
            int can_take = 1;
            for (int j = 0; j < courses[i].prereq_count; j++) {
                int prereq = courses[i].prereqs[j];
                if (!taken[prereq]) {
                    can_take = 0;
                    break;
                }
            }

            if (can_take) {
                best = i;
                break;
            }
        }

        if (best == -1) {
            // Should not happen per problem assumption
            break;
        }

        taken[best] = 1;
        total_credits += courses[best].credits;
        courses_taken++;
    }

    printf("%d\n", courses_taken);

    return 0;
}

