void dfs(int v) {
    dp[v][1] = credits[v];
    sz[v] = 1;
    for (int i = 0; i < nchildren[v]; i++) {
        int c = children[v][i];
        dfs(c);
        // merge subtree c into v's dp
        // temp array
        int tmp[MAXN];
        memset(tmp, 0, sizeof(tmp));
        for (int j = 1; j <= sz[v]; j++) {
            if (dp[v][j] == 0 && j > 1) continue;
            for (int l = 1; l <= sz[c]; l++) {
                if (dp[c][l] == 0) continue;
                if (tmp[j+l] < dp[v][j] + dp[c][l])
                    tmp[j+l] = dp[v][j] + dp[c][l];
            }
        }
        for (int j = 2; j <= sz[v] + sz[c]; j++)
            if (tmp[j] > dp[v][j]) dp[v][j] = tmp[j];
        sz[v] += sz[c];
    }
}

