#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define INF 1000000000

typedef struct {
    int units;
    int prereq_count;
    int *prereq;
} Course;

static int N, U;
static Course *courses;

/*
Input format assumed:
N U
For each course i = 0..N-1:
  units_i k_i p1 p2 ... pk_i

where p1..pk_i are prerequisite course indices (1-based or 0-based both handled).
We convert to 0-based internally.

Goal:
Choose a set of courses such that if a course is chosen, all its prerequisites are chosen,
total units >= U, and number of chosen courses is minimized.

This is solved by enumerating all subsets (works for small N, as is typical for this problem).
The statement does not provide explicit limits in the prompt, so this standard closure-check
solution is used.
*/

int main(void) {
    if (scanf("%d %d", &N, &U) != 2) return 0;

    courses = (Course *)malloc(sizeof(Course) * N);
    if (!courses) return 0;

    for (int i = 0; i < N; i++) {
        int k;
        scanf("%d %d", &courses[i].units, &k);
        courses[i].prereq_count = k;
        courses[i].prereq = (int *)malloc(sizeof(int) * k);
        for (int j = 0; j < k; j++) {
            scanf("%d", &courses[i].prereq[j]);
        }
    }

    /* Detect whether prerequisites are given 1-based. */
    int one_based = 0;
    for (int i = 0; i < N; i++) {
        for (int j = 0; j < courses[i].prereq_count; j++) {
            if (courses[i].prereq[j] >= 1 && courses[i].prereq[j] <= N) {
                one_based = 1;
            }
        }
    }
    if (one_based) {
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < courses[i].prereq_count; j++) {
                courses[i].prereq[j]--;
            }
        }
    }

    int best = INF;

    if (N >= 63) {
        /* Subset enumeration would be infeasible; prompt lacks constraints.
           Still, avoid undefined shift behavior. */
        return 0;
    }

    unsigned long long total = 1ULL << N;
    for (unsigned long long mask = 0; mask < total; mask++) {
        int cnt = 0, sum = 0;
        int ok = 1;

        for (int i = 0; i < N; i++) {
            if ((mask >> i) & 1ULL) {
                cnt++;
                if (cnt >= best) { ok = 0; break; }
                sum += courses[i].units;
            }
        }
        if (!ok || sum < U) continue;

        for (int i = 0; i < N && ok; i++) {
            if ((mask >> i) & 1ULL) {
                for (int j = 0; j < courses[i].prereq_count; j++) {
                    int p = courses[i].prereq[j];
                    if (p < 0 || p >= N || (((mask >> p) & 1ULL) == 0)) {
                        ok = 0;
                        break;
                    }
                }
            }
        }

        if (ok && cnt < best) best = cnt;
    }

    printf("%d\n", best);

    for (int i = 0; i < N; i++) free(courses[i].prereq);
    free(courses);

    return 0;
}

