int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N, U;
    cin >> N >> U;
    vector<int> credit(N);
    for (int i = 0; i < N; i++) {
        cin >> credit[i];
    }

    vector<vector<int>> prereq(N);
    for (int i = 0; i < N; i++) {
        int k;
        cin >> k;
        prereq[i].resize(k);
        for (int j = 0; j < k; j++) {
            cin >> prereq[i][j];
            prereq[i][j]--; // convert to 0-based
        }
    }

    // topological order using Kahn's algorithm
    vector<int> indeg(N, 0);
    for (int i = 0; i < N; i++) {
        for (int p : prereq[i]) {
            indeg[i]++;
        }
    }

    queue<int> q;
    for (int i = 0; i < N; i++) {
        if (indeg[i] == 0) q.push(i);
    }

    vector<int> topo;
    while (!q.empty()) {
        int u = q.front(); q.pop();
        topo.push_back(u);
        // No outgoing edges stored, but we simulate by checking all courses
        // that have u as prerequisite
        for (int v = 0; v < N; v++) {
            for (int p : prereq[v]) {
                if (p == u) {
                    indeg[v]--;
                    if (indeg[v] == 0) q.push(v);
                }
            }
        }
    }

    // DP: dp[i] = min courses to get exactly i credits using processed courses
    // We'll process in topological order to respect prerequisites
    const int INF = 1e9;
    int maxCredit = accumulate(credit.begin(), credit.end(), 0);
    vector<int> dp(maxCredit + 1, INF);
    dp[0] = 0;

    // We need to know which courses are available at each step.
    // For each course in topo order, all its prerequisites are already processed.
    vector<bool> available(N, false);
    for (int u : topo) {
        // Check if all prerequisites are available
        bool ok = true;
        for (int p : prereq[u]) {
            if (!available[p]) {
                ok = false;
                break;
            }
        }
        if (!ok) continue;
        // Mark as available and update dp in reverse order
        available[u] = true;
        int c = credit[u];
        for (int j = maxCredit; j >= c; j--) {
            if (dp[j - c] != INF) {
                dp[j] = min(dp[j], dp[j - c] + 1);
            }
        }
    }

    int ans = INF;
    for (int j = U; j <= maxCredit; j++) {
        ans = min(ans, dp[j]);
    }
    cout << ans << "\n";

    return 0;
}

