#include <bits/stdc++.h>
using namespace std;

/*
We have n courses, each with credit value c[i], and prerequisite relations.
To take a course, all its prerequisites must also be taken.

Goal: reach total credits >= U with the minimum number of taken courses.

Interpretation:
- The prerequisite graph is a forest of rooted trees, where each course has at most one direct prerequisite.
  (This is the standard formulation for this problem type.)
- If course v requires p, then choosing v forces choosing all ancestors up to the root.
- Therefore, for each tree, any feasible chosen set is just several root-to-node prefixes.

DP on tree:
Let dp[u][k] = maximum credits obtainable by choosing exactly k courses from subtree of u,
under the condition that u is chosen.
Then initialize dp[u][1] = credit[u].
For each child, merge:
- either choose nothing from that child's subtree
- or choose t >= 1 courses according to dp[child][t]

After computing all roots, do knapsack over roots:
best[k] = maximum credits using exactly k courses from processed roots.

Finally, answer smallest k with best[k] >= U.

Input format assumed:
n U
for i = 1..n:
    credit_i prereq_i
where prereq_i = 0 means no prerequisite, otherwise prereq_i is the prerequisite course.

This is the classic format for such problem statements.
*/

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    long long U;
    if (!(cin >> n >> U)) return 0;

    vector<int> credit(n + 1), parent(n + 1, 0);
    vector<vector<int>> children(n + 1);
    vector<int> roots;

    for (int i = 1; i <= n; ++i) {
        cin >> credit[i] >> parent[i];
        if (parent[i] == 0) roots.push_back(i);
        else children[parent[i]].push_back(i);
    }

    vector<int> sz(n + 1, 0);
    vector<vector<long long>> dp(n + 1);

    function<void(int)> dfs = [&](int u) {
        sz[u] = 1;
        dp[u] = vector<long long>(2, LLONG_MIN / 4);
        dp[u][1] = credit[u];

        for (int v : children[u]) {
            dfs(v);
            vector<long long> ndp(sz[u] + sz[v] + 1, LLONG_MIN / 4);

            for (int i = 1; i <= sz[u]; ++i) {
                if (dp[u][i] <= LLONG_MIN / 10) continue;

                // take nothing from child subtree
                ndp[i] = max(ndp[i], dp[u][i]);

                // take t >= 1 from child subtree
                for (int t = 1; t <= sz[v]; ++t) {
                    if (dp[v][t] <= LLONG_MIN / 10) continue;
                    ndp[i + t] = max(ndp[i + t], dp[u][i] + dp[v][t]);
                }
            }

            sz[u] += sz[v];
            dp[u].swap(ndp);
        }
    };

    for (int r : roots) dfs(r);

    vector<long long> best(n + 1, LLONG_MIN / 4);
    best[0] = 0;
    int used = 0;

    for (int r : roots) {
        vector<long long> nbest(used + sz[r] + 1, LLONG_MIN / 4);
        for (int i = 0; i <= used; ++i) {
            if (best[i] <= LLONG_MIN / 10) continue;

            // choose nothing from this root's tree
            nbest[i] = max(nbest[i], best[i]);

            // choose t >= 1 from this tree
            for (int t = 1; t <= sz[r]; ++t) {
                if (dp[r][t] <= LLONG_MIN / 10) continue;
                nbest[i + t] = max(nbest[i + t], best[i] + dp[r][t]);
            }
        }
        used += sz[r];
        best.swap(nbest);
    }

    for (int k = 0; k <= n; ++k) {
        if (best[k] >= U) {
            cout << k << '\n';
            return 0;
        }
    }

    return 0;
}

