            int k = Integer.parseInt(st.nextToken());
            for (int j = 0; j < k; j++) {
                int prereq = Integer.parseInt(st.nextToken()) - 1;
                prereqs[prereq].add(i);
                indegree[i]++;
            }
        }

        // Topological sort to compute total credits including prerequisites
        long[] totalCredits = new long[n];
        Queue<Integer> queue = new LinkedList<>();
        for (int i = 0; i < n; i++) {
            totalCredits[i] = credits[i];
            if (indegree[i] == 0) {
                queue.add(i);
            }
        }

        while (!queue.isEmpty()) {
            int curr = queue.poll();
            for (int next : prereqs[curr]) {
                totalCredits[next] += totalCredits[curr];
                indegree[next]--;
                if (indegree[next] == 0) {
                    queue.add(next);
                }
            }
        }

        // Sort by total credits needed
        Arrays.sort(totalCredits);

        long sum = 0;
        int count = 0;
        for (int i = 0; i < n; i++) {
            sum += totalCredits[i];
            count++;
            if (sum >= u) {
                break;
            }
        }

        System.out.println(count);
    }
}

