import java.io.*;
import java.util.*;

/*
 * Course Planning for Lazy Students
 *
 * We have N courses. Each course has:
 *   - credit units
 *   - zero or more prerequisite courses
 *
 * We must choose a set of courses such that:
 *   1) If a course is chosen, all its prerequisites are also chosen.
 *   2) Total credits >= U.
 *
 * Goal: minimize the number of chosen courses.
 *
 * Assumption from statement: a feasible selection always exists.
 *
 * Key observation:
 * The prerequisite graph is a forest of in-trees:
 * every course has at most one direct prerequisite.
 * (This is the standard formulation of this problem.)
 *
 * Then each chosen set is downward-closed in this forest.
 *
 * We solve with tree DP.
 *
 * DP for each node v:
 *   dp[k] = maximum credits obtainable by choosing exactly k courses
 *           from the subtree of v, under the condition that if any course
 *           in this subtree is chosen, the chosen set is valid.
 *
 * Since choosing a descendant requires choosing all ancestors up to v,
 * any non-empty valid choice from subtree(v) must include v.
 *
 * We compute:
 *   - Option 0: choose nothing from subtree(v) => 0 credits with 0 courses
 *   - Non-empty options: start with choosing v alone, then merge children.
 *
 * After processing all roots, we merge root DPs like knapsack over forest.
 * Finally, find minimum k with totalCredits[k] >= U.
 *
 * Input format assumed:
 *   N U
 *   For i = 1..N:
 *       c p
 *   where c = credits of course i
 *         p = prerequisite of i (0 if none)
 *
 * This is the classic format for this problem.
 */

public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);

            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }

            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static int N, U;
    static int[] credit;
    static ArrayList<Integer>[] children;
    static int[] size;
    static final long NEG = -(1L << 60);

    static long[] dfs(int v) {
        // nonEmpty[k] = max credits using exactly k courses from subtree(v), and must include v
        long[] nonEmpty = new long[2];
        nonEmpty[0] = NEG;
        nonEmpty[1] = credit[v];
        int curSize = 1;

        for (int ch : children[v]) {
            long[] child = dfs(ch); // child[0] = 0, child[t] valid for taking t courses from child subtree
            int childSize = size[ch];

            long[] next = new long[curSize + childSize + 1];
            Arrays.fill(next, NEG);

            for (int i = 1; i <= curSize; i++) {
                if (nonEmpty[i] == NEG) continue;
                for (int j = 0; j <= childSize; j++) {
                    if (child[j] == NEG) continue;
                    next[i + j] = Math.max(next[i + j], nonEmpty[i] + child[j]);
                }
            }

            nonEmpty = next;
            curSize += childSize;
        }

        size[v] = curSize;

        // full dp allows choosing nothing from this subtree
        long[] dp = new long[curSize + 1];
        Arrays.fill(dp, NEG);
        dp[0] = 0;
        for (int k = 1; k <= curSize; k++) dp[k] = nonEmpty[k];
        return dp;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);

        N = fs.nextInt();
        U = fs.nextInt();

        credit = new int[N + 1];
        children = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) children[i] = new ArrayList<>();

        boolean[] hasParent = new boolean[N + 1];

        for (int i = 1; i <= N; i++) {
            int c = fs.nextInt();
            int p = fs.nextInt();
            credit[i] = c;
            if (p != 0) {
                children[p].add(i);
                hasParent[i] = true;
            }
        }

        size = new int[N + 1];

        long[] total = new long[1];
        total[0] = 0;
        int totalSize = 0;

        for (int i = 1; i <= N; i++) {
            if (!hasParent[i]) {
                long[] rootDp = dfs(i);
                int rootSize = size[i];

                long[] next = new long[totalSize + rootSize + 1];
                Arrays.fill(next, NEG);

                for (int a = 0; a <= totalSize; a++) {
                    if (total[a] == NEG) continue;
                    for (int b = 0; b <= rootSize; b++) {
                        if (rootDp[b] == NEG) continue;
                        next[a + b] = Math.max(next[a + b], total[a] + rootDp[b]);
                    }
                }

                total = next;
                totalSize += rootSize;
            }
        }

        for (int k = 0; k <= totalSize; k++) {
            if (total[k] >= U) {
                System.out.println(k);
                return;
            }
        }
    }
}
